console.log("this is get all users request");


//step-1

pm.test("Response should be ok and the status code is 200", function(){
    pm.response.to.have.status(200);
});

pm.test("Response should not have a body",function(){
    pm.response.to.not.have.body("error");
});

const res = pm.response.json();
console.log(`this is actual result in json ${res}`);

pm.test("Response should be a non-empty array", function(){
    pm.expect(res).to.be.an('array');
    pm.expect(res.length).to.be.above(0);
});

pm.test("Response should contain user information", function(){
    pm.expect(res[0]).to.have.property('id');
    pm.expect(res[0]).to.have.property('name');
    pm.expect(res[0]).to.have.property('email');
});

pm.test("Each user should have id, name and email", function(){
    res.forEach(function(user){
        pm.expect(user).to.have.property('id');
        pm.expect(user).to.have.property('name');
        pm.expect(user).to.have.property('email');
    });
});


//step-2

pm.environment.set('userId', res[0].id);
pm.environment.set('userName', res[0].name);
console.log("saved userId is " + res[0].id);

console.log("this is pre request for update user");

const oldName = pm.environment.get("userName");
const nName = `${oldName} Updated ${Date.now()}`;
pm.environment.set("newName", nName);

const nEmail = `user${Date.now()}@example.com`;
pm.environment.set("newEmail", nEmail);

const nCompany = `Company Updated ${Date.now()}`;
pm.environment.set("newCompany", nCompany);

console.log("this is update user request");

const resp = pm.response.json();
console.log(resp);

pm.test("Status code is 200", function(){
    pm.expect(pm.response.code).to.eql(200);
});

pm.test("response should not be empty", function(){
    pm.expect(resp).to.not.be.empty;
});

pm.test("Returned ID should match saved ID", function(){
    const savedId = pm.environment.get('userId');
    pm.expect(resp.id).to.eql(Number(savedId));
});

pm.test("Phone should not be empty", function(){
    pm.expect(resp.phone).to.not.be.empty;
});

pm.test("Returned name should match updated name", function(){
    const expectedName = pm.environment.get('newName');
    pm.expect(resp.name).to.eql(expectedName);
});
